INSERT INTO public.tourism_faq (id,category,question_en,question_zh,answer_en,answer_zh,aliases,sources) VALUES
('CN001','arrival','How should I prepare for my first trip to China?','第一次去中国旅游需要做哪些准备？','Check entry requirements for your passport, book suitable accommodation, arrange payments and connectivity, and keep offline copies of reservations. Start with a manageable route rather than too many cities.','先确认所持护照的入境要求，预订合适的住宿，安排支付和网络，并保存预订信息的离线副本。首次旅行建议选择节奏适中的路线，不要安排过多城市。','["China travel preparation","去中国之前要准备什么"]','[]'),
('CN002','arrival','Do I need a visa to visit China?','去中国旅游需要签证吗？','Entry requirements depend on your nationality, travel document, purpose and route. Check the National Immigration Administration and the Chinese embassy or consulate responsible for your application before booking; this FAQ cannot determine eligibility.','入境要求取决于国籍、旅行证件、入境目的和路线。预订前请向国家移民管理局及负责受理的中国使领馆核实，本问答不能判定个人签证资格。','["tourist visa","中国旅游签证"]','[{"name":"National Immigration Administration","url":"https://en.nia.gov.cn/"}]'),
('CN003','arrival','Can I use visa-free entry or transit in China?','我可以免签入境或过境中国吗？','Visa-free entry and transit have different eligibility conditions, permitted areas and stay limits. Confirm the current rules for your passport, entry port and onward itinerary with the National Immigration Administration and your carrier.','免签入境和过境免签的适用条件、活动区域和停留期限不同。请按所持护照、入境口岸及后续行程，向国家移民管理局和承运人核实最新规定。','["transit without visa","visa free transit","过境免签条件"]','[{"name":"National Immigration Administration","url":"https://en.nia.gov.cn/"}]'),
('CN004','arrival','What passport validity should I check before traveling?','出发前要检查护照哪些信息？','Check your passport''s validity, blank pages and condition against the entry and visa rules that apply to you. Also check airline requirements and any onward destination; do not assume one validity rule applies to every traveler.','请根据适用的入境和签证要求检查护照有效期、空白页和证件状况，并核实航空公司及后续目的地的要求，不要假设所有旅客适用同一标准。','["passport expiry","护照有效期"]','[]'),
('CN005','arrival','What should I check about Chinese customs?','入境中国时海关方面要注意什么？','Review official customs guidance for declarations and restricted items before packing. If unsure about food, medicine, valuables or cash, ask customs rather than guessing; keep prescriptions and purchase documents where relevant.','打包前查阅海关官方的申报及限制物品规定。对食品、药品、贵重物品或现金有疑问时，请向海关咨询，不要猜测；必要时携带处方和购买凭证。','["customs declaration","海关申报"]','[]'),
('CN006','arrival','What should I do after landing in China?','抵达中国机场后应该做什么？','Follow immigration and customs procedures, collect your bags and check your onward transport. Use official airport information desks and licensed transport, and keep your accommodation address available in Chinese.','按指引办理边检和海关手续，领取行李并确认后续交通。优先使用机场官方服务台和正规交通工具，随身保存住宿地点的中文地址。','["arrival checklist","落地机场流程"]','[]'),
('CN007','arrival','Should I buy travel insurance for China?','去中国旅游需要购买旅行保险吗？','Consider cover for medical expenses, disruption and your planned activities. Compare policy exclusions, emergency assistance and claim requirements yourself; carry the insurer''s contact details and do not assume every activity is covered.','可考虑涵盖医疗费用、行程中断及计划活动的保险。请自行比较除外责任、紧急援助和理赔要求，保存保险公司的联系方式，不要假设所有活动都在保障范围内。','["travel insurance","旅游保险保障"]','[]'),
('CN008','arrival','How many cities should I include on a first China trip?','第一次中国旅行应该安排几个城市？','Choose fewer bases and allow time for transfers, rest and local exploration. A city-focused trip or a small group of well-connected destinations is easier to manage than changing hotels every day.','建议减少住宿城市，留出转乘、休息和深入游览的时间。围绕一个城市或少数交通便利的目的地安排行程，通常比每天换酒店更轻松。','["first China itinerary","第一次中国行程安排"]','[]'),
('CN009','arrival','Which travel documents should I carry while sightseeing?','在中国游览时需要携带哪些证件？','Keep your original passport secure and accessible for identity checks and bookings. Store separate copies of your entry documents, reservations, insurance and emergency contacts; copies do not replace originals where required.','妥善保管护照原件，并便于办理实名核验和预订。另存入境证件、订单、保险及紧急联系方式的副本；需要原件时，副本不能替代原件。','["documents for sightseeing","旅游随身证件"]','[]'),
('CN010','arrival','Do mainland China entry rules also cover Hong Kong and Macao?','中国内地的入境规定也适用于香港和澳门吗？','Check mainland China, Hong Kong and Macao entry requirements separately. A journey between them may involve separate border checks, and a return to the mainland may require appropriate re-entry permission.','请分别核实中国内地、香港和澳门的入境要求。往来可能涉及单独的边检手续，返回内地时还需确认是否具备相应的再次入境资格。','["Hong Kong Macao entry","港澳与内地入境"]','[]'),
('CN011','payments','What currency is used in mainland China?','中国内地使用什么货币？','The currency is the renminbi, commonly called yuan, with currency code CNY. Check prices and change carefully, and consult a current source for exchange rates rather than relying on this FAQ.','中国内地使用人民币，常用单位为元，货币代码为 CNY。付款时核对价格和找零；汇率会变化，请查询实时信息，不要以本问答作为汇率依据。','["Chinese currency","人民币是什么"]','[]'),
('CN012','payments','Can foreign tourists use Alipay?','外国游客可以使用支付宝吗？','Alipay offers options for visitors to link supported international bank cards. Complete the app''s verification and check current card support, limits and fees; keep a backup payment method if a transaction fails.','支付宝提供绑定部分境外银行卡的游客支付方式。请按应用要求完成验证，并确认当前支持的卡种、限额和费用；支付失败时应备有其他付款方式。','["pay with Alipay","支付宝绑定外国银行卡"]','[{"name":"State Council: payment guide for visitors","url":"https://english.www.gov.cn/news/202404/11/content_WS6617c858c6d0868f4e8e5f4d.html"}]'),
('CN013','payments','Can foreign tourists use WeChat Pay?','外国游客可以使用微信支付吗？','WeChat Pay offers visitor payment options with supported international cards. Follow the current in-app verification steps and check restrictions and fees; not every card or transaction is guaranteed to work.','微信支付提供支持部分境外银行卡的游客支付方式。请按应用内最新流程完成验证，并确认限制和费用；不能保证每张卡或每笔交易都可使用。','["Weixin Pay","微信绑定境外卡"]','[{"name":"State Council: payment guide for visitors","url":"https://english.www.gov.cn/news/202404/11/content_WS6617c858c6d0868f4e8e5f4d.html"}]'),
('CN014','payments','Can I pay directly with an international bank card?','可以直接用国际银行卡付款吗？','International card acceptance varies by merchant and location. Ask before purchasing, especially at smaller businesses, and carry a backup such as an enabled mobile wallet or appropriate cash.','国际银行卡的受理情况因商户和地点而异，尤其在小商户消费前请先询问。建议准备已开通的移动支付或适量现金作为备用。','["Visa Mastercard acceptance","境外信用卡刷卡"]','[{"name":"State Council: payment guide for visitors","url":"https://english.www.gov.cn/news/202404/11/content_WS6617c858c6d0868f4e8e5f4d.html"}]'),
('CN015','payments','Should I carry cash in China?','在中国旅游需要带现金吗？','Keep a modest amount of renminbi as a backup for connectivity or payment problems. Use authorized withdrawal or exchange services, avoid carrying excessive cash and check official declaration rules if carrying large amounts.','建议准备少量人民币，以应对网络或支付故障。通过正规取款或兑换渠道获取现金，避免携带过多现金；大额携带须核实官方申报规定。','["cash or mobile payment","现金备用"]','[{"name":"State Council: payment guide for visitors","url":"https://english.www.gov.cn/news/202404/11/content_WS6617c858c6d0868f4e8e5f4d.html"}]'),
('CN016','payments','How can I withdraw cash from an ATM?','如何在中国的自动取款机取现金？','Look for an ATM displaying your card network and follow its instructions. Confirm overseas withdrawal settings, fees and limits with your bank, protect your PIN and use bank assistance if your card is retained.','寻找标有银行卡所属网络标识的自动取款机，并按提示操作。向发卡行确认境外取款设置、费用和限额，保护密码；吞卡时向银行求助。','["ATM withdrawal","银行卡取现"]','[]'),
('CN017','payments','Where should I exchange money?','在哪里兑换人民币比较合适？','Use authorized banks or currency-exchange counters and check their current requirements, rates and fees. Bring the requested identification and retain receipts; avoid informal street exchanges.','请使用正规银行或授权兑换点，确认当时所需证件、汇率和费用。携带规定的身份证明并保留凭证，避免街头私下换汇。','["currency exchange","换汇地点"]','[]'),
('CN018','payments','How should I plan a travel budget for China?','如何制定中国旅游预算？','Budget separately for accommodation, intercity travel, local transport, food, attraction bookings and a contingency fund. Compare current quotes for your dates; this FAQ does not provide live prices or a guaranteed daily total.','分别估算住宿、跨城交通、市内交通、餐饮、景点预订和备用金。按出行日期比较实时报价；本问答不提供实时价格，也不保证固定的每日总费用。','["daily travel budget","中国旅游花费"]','[]'),
('CN019','payments','What should I do if a mobile payment fails or needs a refund?','移动支付失败或需要退款时怎么办？','Check the transaction status before trying again to avoid duplicate payments. Contact the merchant and the payment platform through official support, keep the transaction reference, and never share passwords or verification codes.','再次付款前先核实交易状态，避免重复支付。通过官方客服联系商户及支付平台，保存交易单号，不要透露密码或验证码。','["payment declined refund","支付失败退款"]','[]'),
('CN020','payments','Is tipping expected when traveling in China?','在中国旅游需要给小费吗？','Tipping customs vary by setting and provider. Ask about any service charge or tour policy in advance, and do not assume a compulsory tip applies everywhere.','小费习惯因场景和服务提供方而异。可提前询问服务费或旅行团的相关政策，不要假设所有地方都必须付小费。','["tipping etiquette","给小费"]','[]'),
('CN021','connectivity','How can I get a local SIM card in China?','在中国如何办理本地手机卡？','Use an official carrier outlet or authorized airport counter. Ask about passport verification, visitor plans, coverage and activation requirements, and check that your phone is unlocked and compatible.','选择运营商直营网点或机场授权柜台，询问护照实名核验、游客套餐、覆盖范围和激活要求，并确认手机已解锁且兼容当地网络。','["buy a SIM","手机流量卡"]','[]'),
('CN022','connectivity','Can I use an eSIM for a China trip?','去中国旅游可以使用 eSIM 吗？','Check your device''s eSIM support and the provider''s current mainland China coverage, activation and identity requirements before buying. Plans differ in data, calling and routing; do not assume an eSIM provides a local phone number.','购买前确认手机支持 eSIM，并向供应商核实中国内地覆盖、激活和实名要求。套餐的数据、通话和网络路由不同，不要假设 eSIM 一定提供本地号码。','["travel eSIM","电子手机卡"]','[]'),
('CN023','connectivity','Should I use international roaming in China?','在中国应该使用国际漫游吗？','Ask your home carrier about mainland China coverage, data allowances and charges before enabling roaming. Compare it with other legitimate connectivity options and download essential information before arrival.','开通前向原运营商确认中国内地覆盖、流量额度和收费，并与其他正规联网方式比较。抵达前下载必要信息，避免完全依赖即时网络。','["roaming data","境外手机漫游"]','[]'),
('CN024','connectivity','How can I use public Wi-Fi more safely?','在中国如何更安全地使用公共 Wi-Fi？','Confirm the network name with the venue and avoid unknown hotspots. Some networks require sign-in or phone verification; avoid sensitive transactions on untrusted networks and keep mobile data as a backup.','向场所工作人员确认网络名称，避免连接不明热点。部分网络需要登录或手机验证；不要在不可信网络上进行敏感交易，并准备移动数据备用。','["public wifi","公共无线网络"]','[]'),
('CN025','connectivity','Which maps should I use for navigation in China?','在中国导航应该使用什么地图？','Choose a map service with current coverage for your destination and test its language and transit features in advance. Save place names and addresses in Chinese, and confirm routes against station signs or local staff.','选择对目的地覆盖较好的地图服务，提前测试语言和公共交通功能。保存地点中文名和中文地址，并结合车站标识或工作人员建议确认路线。','["navigation app","中国地图导航"]','[]'),
('CN026','connectivity','How can I communicate if I do not speak Chinese?','不会中文在中国旅游怎么沟通？','Download a translation app and offline language resources before traveling. Show short written phrases and Chinese addresses, and ask staff to confirm important booking or allergy details rather than relying only on automatic translation.','出行前下载翻译应用和离线语言资源。使用简短的书面表达及中文地址，重要预订信息或过敏要求应请工作人员确认，不要只依赖机器翻译。','["translation app","language barrier","不会说普通话"]','[]'),
('CN027','connectivity','Will all my usual websites and apps work in China?','在中国能使用平常的网站和应用吗？','Availability can differ by service, network and location. Test essential tools and download booking details and offline alternatives in advance; follow local laws and your provider''s terms rather than relying on uninterrupted access.','服务是否可用会因应用、网络和地点而异。提前测试必要工具，下载订单和离线替代资料，并遵守当地法律及服务条款，不要依赖始终可用的网络访问。','["app availability","网站能否访问"]','[]'),
('CN028','connectivity','Do I need a Chinese phone number for travel bookings?','旅游预订需要中国手机号吗？','Requirements vary by booking platform and venue. Check whether your international number is supported and can receive messages; if it is not, ask the official provider for an alternative booking method rather than borrowing an unknown account.','不同预订平台和场所要求不同。确认是否支持国际号码及能否接收短信；如不支持，请向官方服务方询问其他预订方式，不要借用不明账户。','["phone number verification","订票手机号"]','[]'),
('CN029','connectivity','What power adapter should I pack for China?','去中国需要带什么电源转换插头？','Check both the plug type used at your accommodation and the voltage range printed on each device or charger. A plug adapter does not convert voltage; ask the hotel or manufacturer if you are unsure.','请确认住宿地点的插座类型，以及设备或充电器标注的输入电压范围。插头转换器不能转换电压，不确定时向酒店或设备厂家核实。','["electric sockets","plug adapter","插座电压"]','[]'),
('CN030','connectivity','Can I bring a power bank while traveling in China?','在中国旅行可以携带充电宝吗？','Check current carrier and venue rules for your exact journey, especially flights. Battery labels, certification, capacity and handling requirements may differ; keep labels readable and never assume an item accepted on one journey is accepted on another.','请核实所乘承运人及场所的最新规定，尤其是航空行程。电池标识、认证、容量和携带方式要求可能不同；保持标签清晰，不要以一次获准携带推断所有行程均可。','["portable battery on flights","充电宝飞机规定"]','[]'),
('CN031','transport','How do I book a train ticket in China?','在中国如何预订火车票？','Use China Railway 12306 or an authorized sales channel and follow its identity-verification steps. Enter your name and passport details exactly as required, then check the station, date, train and current boarding instructions.','使用铁路 12306 或授权售票渠道，按要求完成身份核验。准确填写姓名和护照信息，核对车站、日期、车次及最新乘车指引。','["high speed rail booking","bullet train tickets","高铁怎么买票"]','[{"name":"China Railway 12306","url":"https://www.12306.cn/en/"}]'),
('CN032','transport','Can I board a Chinese train with my foreign passport?','外国护照可以乘坐中国火车吗？','China Railway supports ticket purchase using eligible passports under its real-name rules. Carry the original document used for booking and follow station instructions for identity checks; ask staff if an automatic gate cannot read it.','中国铁路实名制支持使用符合要求的护照购票。乘车时携带购票所用证件原件，并按车站指引核验身份；自动闸机无法识读时请向工作人员求助。','["passport at railway gate","护照进高铁站"]','[{"name":"China Railway 12306","url":"https://www.12306.cn/en/"}]'),
('CN033','transport','How should my name appear on a train booking?','火车票上的姓名应该如何填写？','Follow the booking platform''s instructions for names and passport numbers, matching the travel document used. Resolve spelling or identity errors with the official seller before travel instead of assuming staff can change them at boarding.','按购票平台对姓名和护照号码的要求填写，并与所用证件一致。出发前通过官方售票方处理拼写或证件错误，不要假设检票时一定可以修改。','["rail ticket name mismatch","火车票姓名填错"]','[{"name":"China Railway 12306","url":"https://www.12306.cn/en/"}]'),
('CN034','transport','How do I change or refund a train ticket?','火车票怎么改签或退票？','Use the original booking channel and check the current rules for your ticket and departure time. Availability, deadlines and fees can vary; keep the booking reference and confirm the change or refund has completed.','通过原购票渠道操作，并核实该车票及发车时间对应的最新规则。余票、截止时间和费用可能不同；保存订单号并确认改签或退款已完成。','["rail refund","高铁改签退票"]','[{"name":"China Railway 12306","url":"https://www.12306.cn/en/"}]'),
('CN035','transport','How do I use the metro in Chinese cities?','在中国城市如何乘坐地铁？','Check the local metro''s official route map and payment options. Follow security and ticket-gate instructions, confirm the direction and interchange, and check the last service for your route rather than assuming all lines share the same hours.','查看当地地铁官方线路图及付款方式，按要求安检和进站。确认行车方向及换乘站，并查询所乘线路的末班车，不要假设所有线路运营时间相同。','["subway tickets","地铁怎么坐"]','[]'),
('CN036','transport','How can I choose a licensed taxi?','如何乘坐正规出租车？','Use an official taxi rank or a reputable booking service. Check vehicle and driver details, show your destination in Chinese and retain the trip receipt; decline unsolicited rides from people approaching you in terminals.','使用正规出租车候车点或可靠的叫车服务。核对车辆及司机信息，出示目的地中文地址并保留行程凭证；不要接受航站楼内陌生人主动招揽的车辆。','["safe taxi","正规打车"]','[]'),
('CN037','transport','How do I use ride-hailing services in China?','在中国如何使用网约车？','Check the service''s language, payment and phone-verification options before your first ride. Match the plate and driver to the booking, confirm the pickup point, and use in-app support for problems.','首次使用前确认平台语言、支付和手机号验证方式。上车前核对车牌及司机，确认上车地点；遇到问题通过应用内官方客服处理。','["book a Didi","网约车叫车"]','[]'),
('CN038','transport','How should I plan an airport transfer?','机场到酒店的交通怎么安排？','Compare official airport rail, bus and licensed taxi options against your arrival time and luggage needs. Confirm the hotel''s Chinese address and allow flexibility for border procedures, traffic and service changes; this FAQ cannot quote a live journey time.','按抵达时间及行李情况比较机场官方轨道交通、巴士和正规出租车。确认酒店中文地址，并为入境手续、路况和运营变化留出余量；本问答不能提供实时耗时。','["airport to hotel","机场接送"]','[]'),
('CN039','transport','What should I check before a domestic flight in China?','在中国乘坐国内航班要注意什么？','Verify the booking name, required original identity document, airport terminal and airline check-in deadline. Check current baggage and battery rules directly with the carrier and allow time for security.','核对订单姓名、所需身份证件原件、机场航站楼及航空公司值机截止时间。直接向承运人确认最新行李和电池规定，并预留安检时间。','["domestic air travel","国内航班值机"]','[]'),
('CN040','transport','Can tourists use shared bicycles in China?','游客可以使用中国的共享单车吗？','Access depends on the operator''s registration, verification and payment support. Check local cycling rules and designated parking, inspect the bicycle and avoid riding where cycling is prohibited.','能否使用取决于运营商的注册、验证和付款支持情况。遵守当地骑行及停车规定，骑行前检查车辆，不要在禁止骑行的区域使用。','["bike sharing","共享自行车"]','[]'),
('CN041','accommodation','How can I confirm a hotel can check in a foreign passport holder?','如何确认酒店可以办理外国护照入住？','Before booking, contact the property directly about passport check-in, registration and any document requirements. Keep written confirmation and a backup option; a listing alone does not confirm that a particular booking can be processed smoothly.','预订前直接联系酒店，确认护照入住、住宿登记及所需资料，并保留书面确认和备用方案。仅凭平台展示信息，不能保证某笔订单办理入住时没有问题。','["hotels for foreigners","外国人住酒店"]','[]'),
('CN042','accommodation','What documents do I need at hotel check-in?','酒店入住需要什么证件？','Ask your property for its current requirements and carry the original passport and booking confirmation. Provide any required entry or stay information through the property''s official check-in process, not to unsolicited contacts.','向住宿方确认当前要求，并携带护照原件及订单确认。所需入境或停留资料应通过住宿方正规入住流程提供，不要交给主动联系的不明人员。','["hotel passport check in","入住证件"]','[]'),
('CN043','accommodation','Do foreign visitors need accommodation registration?','外国游客需要办理住宿登记吗？','Check the registration obligations that apply to your stay with your accommodation provider and local immigration or public-security authorities. Hotels and private stays may use different processes; do not assume a booking confirmation completes registration.','请向住宿方及当地移民或公安部门确认适用的住宿登记要求。酒店和私人住所的办理流程可能不同，不要把订单确认等同于已经完成登记。','["temporary residence registration","临时住宿登记","入住时酒店工作人员要求办理住宿登记，我应该如何核实流程？"]','[{"name":"National Immigration Administration","url":"https://en.nia.gov.cn/"}]'),
('CN044','accommodation','What if I will arrive at my hotel late at night?','深夜到酒店怎么办？','Tell the property your expected arrival time in advance and confirm reception hours, late-check-in arrangements and reservation retention. Keep a contact method and the address offline in case your flight or transport is delayed.','提前告知预计抵达时间，确认前台服务时间、晚到入住方式及订单保留安排。离线保存联系方式和地址，以应对航班或交通延误。','["late hotel arrival","酒店晚到"]','[]'),
('CN045','accommodation','Which area should I stay in when visiting a city?','到一个城市旅游应该住在哪个区域？','Choose a base near the places you plan to visit and a suitable transport connection. Compare accessibility, noise and late-arrival needs as well as price, and check the exact address rather than relying only on neighborhood labels.','选择靠近计划游览地点、交通合适的住宿区域。除价格外，也比较无障碍条件、噪声及晚到需求，并核对具体地址，不要只看商圈名称。','["best area for hotel","住宿地段选择"]','[]'),
('CN046','accommodation','What should I check about hotel deposits?','酒店押金需要注意什么？','Ask the property about the amount, accepted payment methods, refund process and timing before check-in. Retain the receipt and inspect the room with staff if there is damage; refund timing may depend on the bank or platform.','入住前询问押金金额、付款方式、退还流程和时间，保留凭证。发现房间已有损坏时请工作人员确认；到账时间可能取决于银行或平台。','["hotel security deposit","住宿押金退还"]','[]'),
('CN047','accommodation','Can I store luggage before check-in or after check-out?','入住前或退房后可以寄存行李吗？','Ask your accommodation or an official station service about availability, fees and collection hours. Keep passports, medication and valuables with you, and obtain a luggage receipt where provided.','向住宿方或车站正规服务点询问是否提供寄存、费用及取件时间。护照、药品和贵重物品随身携带，并在可提供时索取寄存凭证。','["luggage storage","行李寄存"]','[]'),
('CN048','accommodation','What should I check before booking a hostel?','预订青年旅舍要注意什么？','Confirm passport check-in, room type, lockers, bathroom arrangements and reception access. Read recent reviews and verify any age or room restrictions with the property instead of assuming every listing has the same policies.','确认护照入住、房型、储物柜、卫浴安排和前台开放方式。阅读近期评价，并向住宿方核实年龄或房型限制，不要假设所有房源政策相同。','["hostel booking","青旅住宿"]','[]'),
('CN049','accommodation','What if the guest name on my hotel booking is wrong?','酒店订单入住人姓名填错怎么办？','Contact the original booking platform and the property before arrival. Ask them to correct or confirm the name against the passport and retain written confirmation; do not create duplicate nonrefundable reservations without checking first.','抵达前联系原预订平台和住宿方，请其按护照更正或确认姓名，并保留书面确认。未核实前，不要重复预订不可退款的房间。','["hotel booking name mismatch","酒店姓名错误"]','[]'),
('CN050','accommodation','How do I confirm an accessible hotel room?','如何确认酒店房间的无障碍条件？','Ask for specific details or photos of step-free access, lifts, door widths and bathroom facilities relevant to your needs. Request written confirmation for the actual room type; a generic accessibility label may not describe every part of the property.','按自身需求索取无台阶通道、电梯、门宽及卫浴设施的具体信息或照片。请酒店书面确认实际房型；笼统的无障碍标签不一定代表酒店所有区域。','["wheelchair accessible hotel","无障碍客房"]','[]'),
('CN051','food','How can I order food if the menu is only in Chinese?','菜单只有中文时如何点餐？','Use menu photos or a translation tool and ask staff to confirm ingredients, portion sizes and the total price. Show written dietary requirements, and do not assume an image or translation proves a dish is suitable for an allergy.','可借助图片菜单或翻译工具，请工作人员确认食材、份量和总价。书面展示饮食要求，不要仅凭图片或翻译判断菜品是否适合过敏者。','["Chinese menu ordering","看不懂菜单"]','[]'),
('CN052','food','How can I find vegetarian food in China?','在中国如何寻找素食？','Explain which ingredients you avoid, including meat stock, lard and seafood sauces if relevant. Look for dedicated vegetarian venues and confirm each dish with staff; a vegetable dish is not automatically vegetarian.','明确说明不吃的食材，必要时包括肉汤、猪油和海鲜酱料。可选择专门的素食餐厅，并逐道向工作人员确认；蔬菜菜品不一定完全是素食。','["vegetarian restaurants","吃素怎么点菜"]','[]'),
('CN053','food','How can I find vegan food in China?','在中国如何寻找纯素食物？','Use a written explanation that excludes meat, fish, eggs, dairy and other animal ingredients you avoid. Confirm sauces, stock and shared preparation with the restaurant rather than relying on a vegetarian label alone.','用书面说明明确排除肉类、鱼、蛋、乳制品及其他不食用的动物成分。向餐厅确认酱料、汤底和共用操作情况，不要只依赖素食标签。','["vegan meals","不吃蛋奶纯素"]','[]'),
('CN054','food','How should I explain a food allergy while traveling?','旅游时如何说明食物过敏？','Carry a clear Chinese allergy card naming the ingredient and cross-contact concern, and ask staff to confirm they can meet it. If they cannot verify ingredients or preparation, do not rely on the dish being safe; seek urgent local help for a serious reaction.','携带明确写出过敏食材及交叉接触风险的中文过敏卡，并请工作人员确认能否满足。无法核实食材或制作过程时，不要假设食物安全；严重反应应立即寻求当地紧急援助。','["peanut allergy","食物过敏卡"]','[]'),
('CN055','food','How can I find halal food in China?','在中国如何寻找清真食品？','Look for clearly identified halal restaurants and ask about their ingredients and preparation standards. If your requirements are strict, verify certification or practices directly instead of relying only on a translated menu or map label.','寻找明确标识的清真餐厅，并询问食材及制作规范。如有严格要求，请直接核实认证或操作方式，不要仅凭翻译菜单或地图标签判断。','["halal restaurants","清真餐厅"]','[]'),
('CN056','food','What drinking water should I use while traveling?','在中国旅游饮水要注意什么？','Use drinking water that the accommodation or venue identifies as suitable, or sealed bottled water. Do not assume tap water is ready to drink without treatment; ask staff if you are uncertain about a water source.','选择住宿方或场所明确标为可饮用的水，或密封瓶装水。不要假设自来水未经处理即可饮用；不确定水源时请询问工作人员。','["tap water drinking","自来水能喝吗"]','[]'),
('CN057','food','How can I ask for less spicy food?','如何要求菜品少辣或不辣？','Show the phrase ''不要辣椒，请做不辣的'' to ask for no chili and a non-spicy dish. Confirm chili oil and sauces too, and choose another dish if the recipe cannot be changed.','可以说明“不要辣椒，请做不辣的”，并进一步确认是否含辣椒油和辣酱。如菜品本身无法调整，可换一道适合的菜。','["non spicy food","不要辣椒"]','[]'),
('CN058','food','What should I check when trying street food?','尝试街头小吃要注意什么？','Choose vendors with visible food handling and a clean setup, and favor food prepared and served appropriately. Confirm ingredients and avoid anything that seems poorly stored; popularity alone does not guarantee food safety.','选择操作过程可见、环境整洁的摊位，关注制作、保存及供应方式。确认食材，避免存放状况不明的食品；排队人多并不代表一定安全。','["street food safety","夜市小吃"]','[]'),
('CN059','food','What chopstick etiquette should visitors know?','游客需要了解哪些筷子礼仪？','Avoid sticking chopsticks upright in rice or using them to point at people. Follow your hosts'' cues and use serving utensils when provided; it is fine to ask politely for a fork or spoon.','避免把筷子竖插在米饭中，或用筷子指人。参考主人的习惯，提供公筷公勺时应使用；需要叉勺时可以礼貌提出。','["chopsticks manners","用筷子礼貌"]','[]'),
('CN060','food','How should I explore regional Chinese food?','如何体验中国不同地区的饮食？','Try a small selection of local dishes and ask about ingredients and portion sizes before ordering. Regional styles vary greatly, so do not assume all Chinese food is spicy or that one menu represents the whole country.','可从少量当地菜品开始，点餐前询问食材和份量。各地风味差异很大，不要认为所有中餐都辣，也不要把一份菜单当作全国饮食的代表。','["regional cuisine","地方特色菜"]','[]'),
('CN061','sightseeing','What is West Lake and why is it culturally significant?','西湖是什么，为什么具有文化意义？','West Lake in Hangzhou is a UNESCO-listed cultural landscape shaped by the relationship between its lake, hills, gardens, temples, pagodas and causeways. Explore the scenery and cultural setting at a gentle pace, and confirm current access arrangements separately.','杭州西湖是联合国教科文组织列入名录的文化景观，其湖泊、山丘、园林、寺庙、塔和堤共同构成了重要的文化环境。适合放慢脚步欣赏景观与文化，实际开放安排请另行核实。','["Tell me about West Lake","Tell me about West Lake and why it is culturally significant","推荐杭州西湖","西湖有什么文化价值","West Lake heritage"]','[{"name":"UNESCO: West Lake Cultural Landscape","url":"https://whc.unesco.org/en/list/1334/"}]'),
('CN062','sightseeing','How can I plan a relaxed day in Hangzhou?','如何安排轻松的杭州一日游？','For a gentle Hangzhou day, focus on West Lake rather than crossing the whole city. Consider a lakeside walk including part of the Su Causeway, a rest break, and a view toward Leifeng Pagoda if access and your mobility allow. This is a planning suggestion, not a verified timed route; check transport and venue access before leaving.','轻松的杭州一日游可集中在西湖周边，不必横跨全城。可考虑走一段苏堤、适时休息，并在开放条件及体力允许时欣赏雷峰塔一带景观。这是规划建议，不是核实过的定时路线；出发前确认交通与开放安排。','["Recommend places in Hangzhou","Plan a calm one-day trip around Hangzhou''s verified heritage attractions","Hangzhou day trip","杭州一日游","安排一天轻松的杭州文化遗产之旅"]','[{"name":"UNESCO: West Lake Cultural Landscape","url":"https://whc.unesco.org/en/list/1334/"}]'),
('CN063','sightseeing','How does the Grand Canal compare with West Lake?','大运河与西湖的游览体验有什么不同？','West Lake emphasizes a designed lake-and-hill cultural landscape; the Grand Canal highlights the history of a large engineered waterway and the communities around it. For a history-focused Hangzhou visit, choose the setting that interests you most, or visit them separately without assuming they share one entrance or schedule.','西湖突出湖山与人文景观的结合，大运河更侧重大型人工水道及沿岸社区的历史。杭州历史主题游可按兴趣选择，也可分别游览；不要假设两者共用入口或开放时间。','["Grand Canal history","Compare West Lake and the Grand Canal for a history-focused visitor","西湖和大运河哪个更适合历史游","介绍大运河"]','[{"name":"UNESCO: West Lake Cultural Landscape","url":"https://whc.unesco.org/en/list/1334/"},{"name":"UNESCO: The Grand Canal","url":"https://whc.unesco.org/en/list/1443/"}]'),
('CN064','sightseeing','What should I consider before visiting the Great Wall?','游览长城前要考虑什么？','The Great Wall is a UNESCO World Heritage property with different visitor sections. Choose an officially open section that suits your mobility, check local weather and access, and never enter closed or unrestored sections without authorized access.','长城是世界遗产，不同游览段的条件不同。请选择正式开放、适合自身体力的区段，确认天气与开放情况，不要擅自进入封闭或未授权开放的区域。','["Great Wall visit","长城旅游建议"]','[{"name":"UNESCO: The Great Wall","url":"https://whc.unesco.org/en/list/438/"}]'),
('CN065','sightseeing','How should I prepare for a Forbidden City visit?','参观故宫前应该如何准备？','Use the Palace Museum''s official channels to check current reservations, identity requirements, entrances and closures. Plan a manageable museum visit with rest breaks, and do not rely on this FAQ for live ticket availability or opening hours.','请通过故宫博物院官方渠道确认当期预约、证件要求、入口及闭馆安排。合理规划参观范围并安排休息，不要以本问答判断实时余票或开放时间。','["Palace Museum booking","故宫预约参观"]','[]'),
('CN066','sightseeing','How can I plan a first sightseeing day in Shanghai?','第一次到上海如何安排一天游览？','Choose a compact theme, such as a riverside walk around the Bund or a neighborhood-and-museum day, rather than crossing the city repeatedly. Check the exact venues and transport for your dates; this is general planning guidance, not a live route or booking.','可选外滩滨水散步，或街区与博物馆结合等紧凑主题，避免反复横穿全城。按出行日期核实具体场所和交通；这只是一般规划建议，并非实时路线或预订。','["Shanghai highlights","上海一日游"]','[]'),
('CN067','sightseeing','How should I plan a visit to the Terracotta Army?','如何安排兵马俑参观？','Check the Emperor Qinshihuang''s Mausoleum Site Museum''s official visitor information for bookings and access. Allow time for the exhibition setting and travel from your base in Xi''an, without assuming a fixed journey time or ticket price.','通过秦始皇帝陵博物院官方游客信息确认预订与入园安排。为展览参观及从西安住宿地往返留出时间，不要假设交通耗时或票价固定不变。','["Terracotta Warriors","西安兵马俑旅游"]','[]'),
('CN068','sightseeing','What should I know before visiting pandas in Chengdu?','在成都看大熊猫前需要了解什么？','Confirm the chosen facility''s official booking and visitor rules, and plan for walking and rest. Animal visibility is not guaranteed; keep your distance, stay quiet and never feed or disturb wildlife.','通过所选场所官方渠道确认预约与参观规定，安排步行和休息。不能保证一定看到动物；保持距离、轻声参观，不要投喂或干扰野生动物。','["Chengdu panda visit","成都看熊猫"]','[]'),
('CN069','sightseeing','How can I plan a scenery-focused trip around Guilin?','桂林山水游应该如何规划？','Choose a manageable base and compare official land and water-based sightseeing options for your dates. Check weather, operator credentials and accessibility before booking; water activities and scenic access may change with conditions.','选择合适的住宿点，按日期比较正规陆上和水上游览项目。预订前确认天气、运营资质和无障碍条件；水上活动与景区通行可能随情况变化。','["Guilin scenery","桂林阳朔旅游"]','[]'),
('CN070','sightseeing','How should I choose gardens to visit in Suzhou?','在苏州如何选择园林游览？','Choose a small number of gardens according to your interest in architecture, landscape and quiet walking. Confirm reservations and access through each venue''s official information, and leave time to enjoy details instead of rushing between many sites.','可按建筑、园林景观或安静漫步等兴趣选择少数园林。通过各园官方信息确认预约和通行安排，留出欣赏细节的时间，不必赶看过多景点。','["Suzhou gardens","苏州园林怎么选"]','[]'),
('CN071','planning','Do attractions in China require advance reservations?','中国景点需要提前预约吗？','Reservation requirements vary by attraction, date and visitor category. Check the venue''s official channel before traveling and keep your confirmation; do not assume you can buy a ticket at the entrance.','预约要求因景点、日期和游客类别而异。出发前查看场所官方渠道并保存确认信息，不要假设到门口一定可以买票。','["attraction booking","景区提前订票"]','[]'),
('CN072','planning','How do I book attraction tickets with a foreign passport?','如何使用外国护照预订景点门票？','Check whether the official platform supports your document type and enter the details exactly as required. If it does not, contact the venue''s official support for a permitted alternative and carry the original document used for booking.','确认官方平台是否支持所持证件类型，并按要求准确填写信息。如不支持，请联系景点官方客服询问合规替代方式；参观时携带预订所用证件原件。','["passport attraction tickets","外国人景区实名购票"]','[]'),
('CN073','planning','Where can I check an attraction''s opening hours?','在哪里查询景点开放时间？','Use the attraction''s official website, verified account or visitor hotline for your travel date. Check last entry, weekly closures and temporary notices as well as opening time; this FAQ does not contain live opening hours.','通过景点官网、认证账号或游客热线查询出行日期的安排，同时确认停止入园、例行闭馆和临时公告。本问答不包含实时开放时间。','["current opening hours","景区几点开门"]','[]'),
('CN074','planning','Where can I check current attraction ticket prices?','在哪里查询景点最新票价？','Check the venue''s official ticketing channel for the correct date, ticket category and inclusions. Prices and concessions can change, and add-on transport or exhibitions may be separate; this FAQ does not quote live prices.','通过景点官方售票渠道查询对应日期、票种和包含内容。价格及优惠可能变化，接驳交通或特展可能另计；本问答不提供实时票价。','["admission prices","门票多少钱"]','[]'),
('CN075','planning','How can I avoid holiday crowds while sightseeing?','如何避开节假日旅游人潮？','Check the holiday calendar and official reservation notices before choosing dates. Where possible, use flexible days, less crowded alternatives and advance bookings; no time slot guarantees an uncrowded visit.','选日期前查看节假日安排和官方预约公告。条件允许时使用弹性日期、较少拥挤的替代地点并提前预订；任何时段都不能保证完全没有人潮。','["Golden Week crowds","国庆春节人多"]','[]'),
('CN076','planning','What photography rules should I follow at attractions?','在景点拍照需要遵守什么规定？','Follow posted rules about photography, flash, tripods and restricted areas, and ask permission before photographing people. Drone use requires separate checks with the relevant authorities and venue; a sightseeing ticket does not authorize flight.','遵守场所对拍照、闪光灯、三脚架及限制区域的规定，拍摄人物前先征得同意。无人机需另向主管部门及场所核实；景点门票并不等于飞行许可。','["photography drone rules","景区拍照无人机"]','[]'),
('CN077','planning','How should I plan a museum visit in China?','如何安排中国的博物馆参观？','Choose exhibitions that match your interests and check official reservations, identification, bag and closure rules. Ask about language support and allow rest breaks; a general museum plan does not guarantee access to a particular exhibition.','按兴趣选择展览，并核实官方预约、证件、行李及闭馆规定。可询问语言支持并安排休息；一般参观计划不能保证进入某个特展。','["museum reservations","博物馆怎么参观"]','[]'),
('CN078','planning','What is the best season for a trip to China?','去中国旅游选择什么季节比较好？','China has diverse regional climates, so choose dates for the specific destinations and activities you want. Compare seasonal conditions, crowd patterns and official forecasts near departure instead of assuming one season is best everywhere.','中国不同地区气候差异很大，应根据具体目的地和活动选日期。综合季节特点、人流规律，并在临近出发时查官方预报，不要假设某个季节适合全国所有地区。','["best time to visit China","几月去中国合适"]','[]'),
('CN079','planning','How much time should I allow for sightseeing in one city?','一个城市应该留多少游览时间？','Base the length of stay on your interests, mobility and transfer needs. Leave unplanned time and group nearby attractions together; this FAQ cannot guarantee a fixed number of days will cover every city or visitor''s needs.','按兴趣、体力和转乘需求安排停留时间，保留弹性，并把相近景点放在一起。不同城市和游客需求不同，本问答不能保证固定天数足以完成所有游览。','["how many days per city","城市游玩天数"]','[]'),
('CN080','planning','What can I do on a rainy sightseeing day?','下雨天旅游可以怎么安排？','Consider a museum, indoor cultural venue or a relaxed local meal, after checking current opening and reservation arrangements. Avoid exposed paths or water activities when conditions are unsafe, and follow local weather warnings.','可考虑博物馆、室内文化场所或轻松品尝当地美食，先确认当期开放与预约安排。天气不安全时避开暴露步道和水上活动，并遵从当地预警。','["rainy day itinerary","雨天怎么玩"]','[]'),
('CN081','visitor-needs','How should I behave when visiting temples?','参观寺庙时要注意哪些礼仪？','Dress and behave respectfully, follow posted access and photography rules and keep noise low. Ask before joining rituals or handling objects, and do not enter spaces reserved for worshippers or staff without permission.','穿着举止保持尊重，遵守通行及拍照规定，轻声参观。参与仪式或触碰物品前先询问，不要擅自进入仅供信众或工作人员使用的区域。','["temple etiquette","寺庙礼貌"]','[]'),
('CN082','visitor-needs','What queueing etiquette should I follow?','排队时需要注意什么？','Follow marked queues and staff directions, and allow passengers to exit before boarding. Keep entrances clear and ask staff for assistance if you need accessible boarding rather than pushing through a crowd.','遵守排队标识及工作人员指引，乘车先下后上，不堵塞出入口。需要无障碍协助时请向工作人员提出，不要挤过人群。','["queue manners","排队礼仪"]','[]'),
('CN083','visitor-needs','What should I expect from public toilets?','使用公共卫生间需要注意什么？','Facilities vary, and some locations may have squat toilets or limited supplies. Look for accessible or seated facilities if needed, carry personal essentials and follow local disposal signs.','设施因地点而异，部分场所可能以蹲厕为主或用品有限。如有需要可寻找坐便或无障碍设施，携带个人必需品，并按现场标识处理废弃物。','["public restroom","公共厕所蹲厕"]','[]'),
('CN084','visitor-needs','Should I carry tissues and hand sanitizer while sightseeing?','游览时需要带纸巾和洗手用品吗？','A small personal supply of tissues and hand-cleaning products can be useful because facilities vary. Follow transport rules for liquids and aerosols and use available handwashing facilities appropriately.','可少量携带纸巾和清洁用品，因为不同场所配置不同。遵守交通工具对液体和喷雾的限制，并适当使用现场洗手设施。','["toiletry day bag","随身纸巾洗手液"]','[]'),
('CN085','visitor-needs','How can I plan a China trip with children?','带孩子去中国旅游怎么规划？','Use a slower pace with rest, meals and suitable indoor alternatives. Confirm child ticket, bedding and transport requirements with each provider and keep identification and family contact information accessible; age rules vary by service.','放慢节奏，安排休息、用餐及合适的室内备选活动。逐一向服务方确认儿童票、床位及交通要求，便于取用证件和家庭联系方式；不同服务的年龄标准可能不同。','["family travel with kids","亲子游"]','[]'),
('CN086','visitor-needs','How can I plan wheelchair-accessible sightseeing?','轮椅使用者如何安排游览？','Confirm step-free entrances, lift access, surfaces, toilets and transport for each venue directly. Ask about the complete route, not just the entrance, and prepare an alternative if weather or equipment makes access unsuitable.','逐一向场所确认无台阶入口、电梯、路面、卫生间及交通接驳。应核实全程通行条件，而不只是入口；天气或设备不适合时准备替代方案。','["wheelchair tourism","无障碍景点路线"]','[]'),
('CN087','visitor-needs','How can I plan a comfortable trip for older travelers?','如何为老年游客安排舒适行程？','Choose fewer stops, easy transport and regular rest breaks, and confirm lifts and walking conditions. Discuss individual health needs with a qualified professional before travel; do not assume every attraction offers the same concessions or access.','减少每日停靠点，选择便利交通并定时休息，提前确认电梯和步行条件。个人健康需求请在出行前咨询合格专业人员；不同景点的优惠和通行条件并不相同。','["senior travel","老人旅游安排"]','[]'),
('CN088','visitor-needs','What should I pack for everyday sightseeing?','日常游览应该带什么？','Pack suitable walking shoes, weather-appropriate layers, drinking water, essential documents and a charged phone. Keep the bag light and check venue and transport restrictions before bringing bulky items, batteries or liquids.','准备合适的步行鞋、应季衣物、饮水、必要证件及充好电的手机。尽量轻装，携带大件物品、电池或液体前核实景点和交通规定。','["sightseeing packing list","旅游随身物品"]','[]'),
('CN089','visitor-needs','Where should I check weather and travel warnings?','在哪里查看天气和出行预警？','Check official local forecasts, emergency-management notices and transport or attraction announcements close to departure. Recheck during your trip and change plans if warnings affect your route; this FAQ has no live weather feed.','临近出发时查看当地官方天气预报、应急提示及交通或景点公告。旅行中继续关注，预警影响路线时调整计划；本问答没有实时天气数据。','["weather forecast alerts","旅游天气预警"]','[]'),
('CN090','visitor-needs','How can I travel more responsibly in China?','如何在中国进行更负责任的旅游？','Use appropriate public transport where practical, reduce waste and stay on permitted routes. Respect local communities, wildlife and cultural objects, and follow site rules instead of disturbing a place for a photograph.','条件合适时使用公共交通、减少废弃物，并沿允许的路线游览。尊重社区、野生动物及文物，遵守场所规定，不要为了拍照干扰环境。','["sustainable tourism","低碳文明旅游"]','[]'),
('CN091','assistance','What should I do if I lose my passport in China?','在中国遗失护照怎么办？','Contact your embassy or consulate and the local police or immigration authority for the required reporting and replacement steps. Keep copies of your identity and entry records available, and check travel changes with your carrier; replacement documents and exit procedures need official confirmation.','请联系本国使领馆及当地公安或移民管理部门，确认报失、补办和后续手续。准备身份及入境记录副本，并向承运人确认行程调整；补发证件及出境流程须由官方核实。','["lost passport","护照丢了"]','[{"name":"National Immigration Administration","url":"https://en.nia.gov.cn/"}]'),
('CN092','assistance','What should I do if I lose my phone while traveling?','旅游时手机丢了怎么办？','Use a trusted device to secure important accounts and contact your mobile carrier and payment providers through official channels. Ask the venue or transport operator about lost property and report suspected theft to local police; do not share recovery codes with strangers.','使用可信设备保护重要账户，通过官方渠道联系运营商及支付平台。向场所或交通运营方询问失物招领，怀疑被盗时报警；不要向陌生人提供账户恢复验证码。','["lost mobile phone","手机遗失","旅游途中怎样保管手机并在丢失后保护自己的支付账户？"]','[]'),
('CN093','assistance','What should I do if I lose my wallet or bank cards?','钱包或银行卡丢了怎么办？','Contact your bank immediately through an official number to block affected cards and review transactions. Check with the venue''s lost-property desk and report suspected theft; arrange a secure backup payment method without sharing PINs or passwords.','立即通过银行官方号码联系挂失相关卡片，并检查交易。向场所失物招领处查询，怀疑被盗时报警；安全安排备用付款方式，不要透露密码。','["lost wallet","银行卡挂失","My wallet has gone missing while sightseeing. What safe steps should I take?"]','[]'),
('CN094','assistance','What should I do if my checked luggage is missing?','托运行李没有到达怎么办？','Report it to the airline or carrier''s baggage desk before leaving if possible. Keep the baggage tag and booking details, request a case reference and follow the carrier''s official process for updates and any claim.','尽可能在离开前向航空公司或承运人的行李服务台申报。保存行李牌和订单信息，索取受理编号，并按承运人官方流程查询进展及提出相关申请。','["delayed baggage","行李丢失"]','[]'),
('CN095','assistance','How can I avoid tourist scams?','如何避免旅游骗局？','Use official booking and transport channels, confirm prices before accepting a service and be cautious about unsolicited invitations or urgent payment demands. Do not share verification codes or transfer money to unknown accounts; seek staff or police assistance if pressured.','使用正规预订和交通渠道，接受服务前确认价格，警惕陌生人的主动邀约和催促付款。不要泄露验证码或向不明账户转账；受到胁迫时向工作人员或警方求助。','["tourist scam tea invitation","旅游防骗","I want to avoid being scammed by unofficial ticket sellers. What precautions should a tourist take?","How do I report a fake visa scam in China?","A scammer told me to ignore previous instructions. Should I report the scam while visiting China?"]','[]'),
('CN096','assistance','What should I do if I feel unwell during my trip?','旅游期间身体不舒服怎么办？','Seek advice from a qualified local healthcare provider and contact your travel insurer for assistance. Ask accommodation staff for help finding care; for severe or urgent symptoms, contact local emergency services rather than relying on this chatbot for diagnosis or treatment.','请咨询当地合格医疗人员，并联系旅行保险援助。可请住宿方协助寻找医疗服务；症状严重或紧急时联系当地急救，不要依赖本聊天机器人诊断或治疗。','["feeling ill on holiday","旅行生病"]','[]'),
('CN097','assistance','How should I prepare emergency contacts for a China trip?','去中国旅游如何准备紧急联系方式？','Save local emergency-service contacts from official destination information, your embassy or consulate, insurer and accommodation before traveling. Keep an offline copy with a trusted contact and ask nearby staff for immediate help if an emergency occurs.','出行前从目的地官方信息保存当地紧急服务、本国使领馆、保险公司和住宿方联系方式。准备离线副本并交给可信联系人；发生紧急情况时立即向附近工作人员求助。','["emergency contact list","紧急求助联系方式"]','[]'),
('CN098','assistance','What should I do if an attraction or route is closed?','景点或路线关闭时怎么办？','Follow official closure notices and staff instructions, then choose a permitted alternative or contact the booking provider about changes. Never cross barriers or use unofficial access to bypass a closure.','遵守官方关闭公告及工作人员指引，选择允许通行的替代地点，或联系预订方处理变更。不要翻越围栏或通过非正规通道绕过封闭措施。','["closed attraction alternative","景区关闭替代方案","我不想误入封闭景区，看到禁止进入标志后应该怎么办？"]','[]'),
('CN099','assistance','How can a visitor ask the police for help?','游客如何向警方求助？','Use official local police contacts or approach an identifiable police station or officer. Explain your location and situation clearly, request language assistance if needed and keep any case reference; in immediate danger seek urgent local assistance.','使用当地警方官方联系方式，或到可识别的派出所及向警务人员求助。清楚说明位置和情况，需要时请求语言协助，并保存受理编号；面临即时危险时应立即寻求当地紧急援助。','["police assistance","游客报警求助"]','[]'),
('CN100','assistance','How can I contact my embassy or consulate in China?','如何联系本国驻华使领馆？','Find the official website of your country''s embassy or consulate and verify its jurisdiction, opening arrangements and emergency contact. Use official channels for consular help, and remember that consular assistance does not replace local emergency services.','查询本国驻华使领馆官网，核实领区、办公安排及紧急联系方式。通过官方渠道申请领事协助；领事服务不能替代当地紧急救援。','["consular assistance","使馆领事求助"]','[]')
