-- Apply faq-schema.sql first. Upsert these 100 canonical FAQs.
BEGIN;
ON CONFLICT (id) DO UPDATE SET category=excluded.category,question_en=excluded.question_en,question_zh=excluded.question_zh,answer_en=excluded.answer_en,answer_zh=excluded.answer_zh,aliases=excluded.aliases,sources=excluded.sources;
COMMIT;
